// Every part number in the Loc-Line section of the range guide (Lockwood
// Products' current catalogue, Form 99095), one entry per pack size, in the
// guide's order. `colours` lists the suffixes the part can also be ordered in
// (-BLK black, -G grey, -W white); left out, it comes in the standard
// orange and blue only.

export type LocLineColour = "-BLK" | "-G" | "-W";

export type LocLinePart = {
  part: string;
  name: string;
  /** How many come in the pack, and what they are. */
  pack: string;
  /** A fact the guide prints under the pack, such as an assembled length. */
  note?: string;
  system: string;
  category: string;
  colours?: readonly LocLineColour[];
};

